window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4cb1fca29e8b9134"]={"versions": [{"id": "FIG-4cb1fca29e8b9134", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungslogik).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der normativen Verzweigungslogik innerhalb der inversen Transformationsfunktion (<code>E2EXf_Inv_&lt;TransformerId&gt;</code>) des AUTOSAR Classic E2E-Transformers auf Server-Seite einer Client/Server-Kommunikation (C/S).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im System Services / Transformation Layer direkt an der Schnittstelle zwischen RTE und Kommunikationsstack (COM/SOME/IP). Das Diagramm steuert die Auswahl der E2E-Bibliotheksfunktion zur Integritätsprüfung eingehender Client-Request-Serialisierungen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Transformationskontext:</strong></li>\n<li><code>E2EXf_Inv_&lt;TransformerId&gt;</code>: Ausführender inverser Transformer der Server-Instanz.</li>\n<li><strong>Aufgerufene E2E-Library-APIs:</strong></li>\n<li><code>E2E_PXXSinkCheck()</code> (Farbcodierung <em>Cyan / C/S: Server</em>): Spezifische Prüfroutine für Multi-Client-fähige E2E-Profile (<code>PXXm</code>, z. B. P04m, P07m, P11m, P22m). Verarbeitet Sink-Statusdaten zur Handhabung unabhängiger Sequenzzähler mehrerer Clients.</li>\n<li><code>E2E_PXXCheck()</code> (Farbcodierung <em>Beige / All types</em>): Standard-Prüfroutine der E2E-Bibliothek für Punkt-zu-Punkt- bzw. 1:1-Kommunikationsbeziehungen.</li>\n<li><strong>Variablen & Parameter:</strong></li>\n<li><code>Profile</code>: Konfigurationsparameter des E2E-Transformers (<code>E2EXf</code>), der das zu verwendende E2E-Profil identifiziert.</li>\n<li><code>checkret</code>: Lokale Rückgabevariable vom Typ <code>Std_ReturnType</code> bzw. <code>E2E_PCheckStatusType</code>, die das Prüfergebnis der E2E-Library aufnimmt.</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Exklusive 1:1-Entscheidungsverzweigung (Alternative Guards <code>[TRUE]</code> / <code>[FALSE]</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Synchroner Aufruf von <code>E2EXf_Inv_*</code> bei Empfang einer Request-PDU durch den Server.</li>\n<li><strong>Evaluierung (Decision Node):</strong> Prüfung der Bedingung <code>Profile == PXXm</code>.</li>\n<li><strong>Ausführungspfad [TRUE] (Multi-Client-Profil aktiv):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>checkret = E2E_PXXSinkCheck(Config, State, ...)</code>.</li>\n<li>Berücksichtigt spezifische Sink-Validierungsmechanismen für N:1 Client/Server-Topologien.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführungspfad [FALSE] (Standard-Profil):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>checkret = E2E_PXXCheck(Config, State, ...)</code>.</li>\n<li>Standardmäßige Prüfung von CRC, Alive-Counter und Data-ID.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Merge & Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zusammenführung beider Zweige im Merge-Knoten.</li>\n<li><code>return</code>: Übergabe von <code>checkret</code> an die nachfolgende State-Machine-Verarbeitung (<code>E2E_PXXStateMachineCheck</code>) bzw. Rückkehr an die RTE.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisations- & Fehlerverhalten:</strong> Rein synchroner Ablauf im Ausführungskontext des Empfangstasks; keine asynchronen Callbacks.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong></li>\n<li><code>SWS_E2EXf_00202</code>: Fordert zwingend den Aufruf von <code>E2E_PXXSinkCheck()</code>, wenn für eine Server-C/S-Schnittstelle ein Multi-Client-Profil (<code>PXXm</code>) konfiguriert ist.</li>\n<li><code>SWS_E2EXf_00203</code>: Fordert den Aufruf von <code>E2E_PXXCheck()</code>, wenn kein <code>PXXm</code>-Profil konfiguriert ist.</li>\n<li>Erfüllt <code>RS_E2E_08538</code> zur E2E-Absicherung von Client/Server-Schnittstellen.</li>\n<li><strong>Stack- & Code-Generator-Auswirkung:</strong></li>\n<li>In optimierten BSW-Stacks wird dieser Kontrollfluss nicht zur Laufzeit per <code>if/else</code> evaluiert, sondern vom Transformer-Generator anhand des ARXML-Modells (<code>EndToEndTransformationDescription.profileName</code>) statisch als direkter Funktionsaufruf aufgelöst.</li>\n<li><strong>Integrations- & Fehlerrisiko bei 1:N C/S:</strong></li>\n<li>Rufen mehrere Clients denselben Server-Port auf, führt die Konfiguration eines Standard-Profils (<code>[FALSE]</code>-Pfad) zu deterministischen Counter-Fehlern (<code>E2E_E_WRONGSEQUENCE</code>), da sequentielle Counterstände verschiedener Clients den Monotonie-Check verletzen. Für Multi-Client-C/S ist zwingend ein <code>PXXm</code>-Profil zu wählen.</li>\n<li><strong>Speicherallokation (RAM):</strong></li>\n<li><code>E2E_PXXSinkCheck()</code> erfordert die Allokation und Initialisierung einer separaten Sink-State-Struktur (<code>E2E_PXXSinkStateType</code>), die vom Generator im RAM bereitgestellt und über den Lebenszyklus des Server-Ports gehalten werden muss.</li>\n</ul>"}, {"id": "FIG-450211ad00211660", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungslogik).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der normativen Verzweigungslogik innerhalb der inversen Transformationsfunktion (<code>E2EXf_Inv_&lt;TransformerId&gt;</code>) des AUTOSAR Classic E2E-Transformers auf Server-Seite einer Client/Server-Kommunikation (C/S).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im System Services / Transformation Layer direkt an der Schnittstelle zwischen RTE und Kommunikationsstack (COM/SOME/IP). Das Diagramm steuert die Auswahl der E2E-Bibliotheksfunktion zur Integritätsprüfung eingehender Client-Request-Serialisierungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Transformationskontext:</strong></li>\n<li><code>E2EXf_Inv_&lt;TransformerId&gt;</code>: Ausführender inverser Transformer der Server-Instanz.</li>\n<li><strong>Aufgerufene E2E-Library-APIs:</strong></li>\n<li><code>E2E_PXXSinkCheck()</code> (Farbcodierung <em>Cyan / C/S: Server</em>): Spezifische Prüfroutine für Multi-Client-fähige E2E-Profile (<code>PXXm</code>, z. B. P04m, P07m, P11m, P22m). Verarbeitet Sink-Statusdaten zur Handhabung unabhängiger Sequenzzähler mehrerer Clients.</li>\n<li><code>E2E_PXXCheck()</code> (Farbcodierung <em>Beige / All types</em>): Standard-Prüfroutine der E2E-Bibliothek für Punkt-zu-Punkt- bzw. 1:1-Kommunikationsbeziehungen.</li>\n<li><strong>Variablen & Parameter:</strong></li>\n<li><code>Profile</code>: Konfigurationsparameter des E2E-Transformers (<code>E2EXf</code>), der das zu verwendende E2E-Profil identifiziert.</li>\n<li><code>checkret</code>: Lokale Rückgabevariable vom Typ <code>Std_ReturnType</code> bzw. <code>E2E_PCheckStatusType</code>, die das Prüfergebnis der E2E-Library aufnimmt.</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Exklusive 1:1-Entscheidungsverzweigung (Alternative Guards <code>[TRUE]</code> / <code>[FALSE]</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Synchroner Aufruf von <code>E2EXf_Inv_*</code> bei Empfang einer Request-PDU durch den Server.</li>\n<li><strong>Evaluierung (Decision Node):</strong> Prüfung der Bedingung <code>Profile == PXXm</code>.</li>\n<li><strong>Ausführungspfad [TRUE] (Multi-Client-Profil aktiv):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>checkret = E2E_PXXSinkCheck(Config, State, ...)</code>.</li>\n<li>Berücksichtigt spezifische Sink-Validierungsmechanismen für N:1 Client/Server-Topologien.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführungspfad [FALSE] (Standard-Profil):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aufruf von <code>checkret = E2E_PXXCheck(Config, State, ...)</code>.</li>\n<li>Standardmäßige Prüfung von CRC, Alive-Counter und Data-ID.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Merge & Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zusammenführung beider Zweige im Merge-Knoten.</li>\n<li><code>return</code>: Übergabe von <code>checkret</code> an die nachfolgende State-Machine-Verarbeitung (<code>E2E_PXXStateMachineCheck</code>) bzw. Rückkehr an die RTE.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisations- & Fehlerverhalten:</strong> Rein synchroner Ablauf im Ausführungskontext des Empfangstasks; keine asynchronen Callbacks.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong></li>\n<li><code>SWS_E2EXf_00202</code>: Fordert zwingend den Aufruf von <code>E2E_PXXSinkCheck()</code>, wenn für eine Server-C/S-Schnittstelle ein Multi-Client-Profil (<code>PXXm</code>) konfiguriert ist.</li>\n<li><code>SWS_E2EXf_00203</code>: Fordert den Aufruf von <code>E2E_PXXCheck()</code>, wenn kein <code>PXXm</code>-Profil konfiguriert ist.</li>\n<li>Erfüllt <code>RS_E2E_08538</code> zur E2E-Absicherung von Client/Server-Schnittstellen.</li>\n<li><strong>Stack- & Code-Generator-Auswirkung:</strong></li>\n<li>In optimierten BSW-Stacks wird dieser Kontrollfluss nicht zur Laufzeit per <code>if/else</code> evaluiert, sondern vom Transformer-Generator anhand des ARXML-Modells (<code>EndToEndTransformationDescription.profileName</code>) statisch als direkter Funktionsaufruf aufgelöst.</li>\n<li><strong>Integrations- & Fehlerrisiko bei 1:N C/S:</strong></li>\n<li>Rufen mehrere Clients denselben Server-Port auf, führt die Konfiguration eines Standard-Profils (<code>[FALSE]</code>-Pfad) zu deterministischen Counter-Fehlern (<code>E2E_E_WRONGSEQUENCE</code>), da sequentielle Counterstände verschiedener Clients den Monotonie-Check verletzen. Für Multi-Client-C/S ist zwingend ein <code>PXXm</code>-Profil zu wählen.</li>\n<li><strong>Speicherallokation (RAM):</strong></li>\n<li><code>E2E_PXXSinkCheck()</code> erfordert die Allokation und Initialisierung einer separaten Sink-State-Struktur (<code>E2E_PXXSinkStateType</code>), die vom Generator im RAM bereitgestellt und über den Lebenszyklus des Server-Ports gehalten werden muss.</li>\n</ul>"}], "trans": [{"from": "FIG-4cb1fca29e8b9134", "to": "FIG-450211ad00211660", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Legendenkasten: Überschrift von „Communication Types“ in „Legend“ umbenannt. Ablauflogik und Prüfroutinen sind unverändert.</li>\n</ul>"}]};
